import { ColumnDef, Row } from '@tanstack/react-table';
import { TraineesDetails } from '../../types/configs.types';
import TrashIcon from '@/components/icons/TrashIcon';
import { toast } from 'sonner';
import { useNavigate } from 'react-router-dom';
import ViewIcon from '@/components/icons/ViewIcon';
import { apiDelete } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';

function departmentLabel(row: TraineesDetails) {
    const d = row.department?.trim();
    if (d) return d;
    const s = row.direct_supervisor?.trim();
    if (s) return s;
    return '—';
}

const ActionsCell = ({ row }: { row: Row<TraineesDetails> }) => {
    const navigate = useNavigate();
    const refresh = row.original.refreshTable;

    const handleDelete = async () => {
        const ok = window.confirm('حذف هذا المتدرب نهائياً؟ لا يمكن التراجع عن هذا الإجراء.');
        if (!ok) return;
        try {
            await apiDelete({ endpoint: `${endpoints.trainee.delete}${row.original.id}` });
            toast.success('تم حذف المتدرب', { className: 'font-cairo' });
            refresh?.();
        } catch (e: unknown) {
            const err = e as { response?: { data?: { msg?: string } } };
            toast.error(err.response?.data?.msg || 'تعذر حذف المتدرب', { className: 'font-cairo' });
        }
    };

    return (
        <div className="me-6 text-end flex flex-row items-center justify-end gap-6">
            <button
                type="button"
                onClick={() => navigate(`/human-resources/trainees/${row.original.id}`)}
                className="hover:bg-white-blue-300 rounded-full p-1"
                aria-label="عرض التفاصيل"
            >
                <ViewIcon className="text-primery-blue-400" />
            </button>
            <button type="button" onClick={() => void handleDelete()} className="hover:bg-white-blue-300 rounded-full p-1" aria-label="حذف">
                <TrashIcon className="text-[#E81E1E] cursor-pointer" />
            </button>
        </div>
    );
};

export const columns: ColumnDef<TraineesDetails>[] = [
    {
        accessorKey: 'name',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    اسم المتدرب
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="flex flex-row justify-start items-center gap-4 text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                <p className="tracking-normal text-primery-blue-900 font-medium text-sm">{row.original.name}</p>
            </div>
        ),
    },
    {
        accessorKey: 'department',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    القسم / المشرف
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-[#625E74] leading-[26.24px] font-semibold tracking-normal">
                {departmentLabel(row.original)}
            </div>
        ),
    },
    {
        accessorKey: 'program',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                    البرنامج
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.program ?? '—'}
                </div>
            );
        },
    },
    {
        accessorKey: 'start_date',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                    تاريخ البدء
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.start_date ?? '—'}
                </div>
            );
        },
    },
    {
        accessorKey: 'end_date',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                    تاريخ الانتهاء
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.end_date ?? '—'}
                </div>
            );
        },
    },

    {
        accessorKey: 'attendance_rate',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal text-nowrap">
                    نسبه الحضور
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original.attendance_rate ?? '—'}
                </div>
            );
        },
    },

    {
        id: 'actions',
        header: () => {
            return (
                <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الاجراءات
                </div>
            );
        },
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
