import { useCallback, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { DataTableToolbar } from './data-table-toolbar';
import { columns } from './columns';
import { FetchDataOptions } from '@/types/table.types';
import { DataTable } from '@/components/tables/customTable/data-table';
import { TraineesDetails } from '../../types/configs.types';

export default function TraineesList() {
    const [data, setData] = useState<TraineesDetails[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);

    const fetchData = useCallback(async (options: FetchDataOptions) => {
        setIsLoading(true);
        try {
            const response = await apiGet({
                endpoint: endpoints.trainee.list,
                queryParams: {
                    page: options.pageIndex + 1,
                    pageSize: options.pageSize,
                    ...options.filters,
                    search: options.globalFilter,
                },
            });

            const payload = response.data?.data;
            const rows = Array.isArray(payload?.data) ? (payload.data as TraineesDetails[]) : [];
            const pagination = payload?.pagination;
            const total = pagination?.total ?? 0;
            const perPage = pagination?.per_page ?? options.pageSize ?? 10;

            setData(rows);
            setTotalCount(total);
            setPageCount(total === 0 ? 0 : Math.ceil(total / perPage));
        } catch (error) {
            console.error('Error fetching trainees:', error);
            setData([]);
            setTotalCount(0);
            setPageCount(0);
        } finally {
            setIsLoading(false);
        }
    }, []);

    return (
        <div className="mt-6 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
            <DataTable
                columns={columns}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={DataTableToolbar}
                isLoading={isLoading}
            />
        </div>
    );
}
